from typing import List
from collections import deque

def longest_stable_window(prices: List[int], k: int) -> int:
    mx, mn = deque(), deque()          # indices; values decreasing / increasing
    left = best = 0
    for right, v in enumerate(prices):
        while mx and prices[mx[-1]] <= v:
            mx.pop()
        mx.append(right)
        while mn and prices[mn[-1]] >= v:
            mn.pop()
        mn.append(right)
        while prices[mx[0]] - prices[mn[0]] > k:
            left += 1
            if mx[0] < left:
                mx.popleft()
            if mn[0] < left:
                mn.popleft()
        best = max(best, right - left + 1)
    return best

from typing import List
from collections import deque

def count_shortest_routes(n: int, edges: List[List[int]], src: int, dst: int, min_conf: int) -> List[int]:
    MOD = 10**9 + 7
    adj = [[] for _ in range(n)]
    for u, v, c in edges:
        if c >= min_conf:
            adj[u].append(v)
            adj[v].append(u)
    dist = [-1] * n
    ways = [0] * n
    dist[src], ways[src] = 0, 1
    q = deque([src])
    while q:
        u = q.popleft()
        if u == dst:
            break
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)
            if dist[v] == dist[u] + 1:
                ways[v] = (ways[v] + ways[u]) % MOD
    return [dist[dst], ways[dst] % MOD] if dist[dst] != -1 else [-1, 0]
